@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #131722;
  --bg-surface: #1E222D;
  --bg-surface-hover: #2A2E39;
  --bg-elevated: #252833;
  --bg-input: #1C2030;
  --accent: #2962FF;
  --accent-hover: #3D7AFF;
  --accent-dim: rgba(41, 98, 255, 0.12);
  --positive: #26A69A;
  --positive-bg: rgba(38, 166, 154, 0.1);
  --negative: #F7525F;
  --negative-bg: rgba(247, 82, 95, 0.1);
  --text-primary: #D1D4DC;
  --text-secondary: #787B86;
  --text-muted: #4A4E59;
  --border: #2A2E39;
  --border-light: #363A45;
  --white: #FFFFFF;
  --radius: 6px;
  --radius-lg: 10px;
  --radius-sm: 4px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.4);
  --transition: 150ms ease;
  --transition-mid: 250ms ease;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'SF Mono', 'Fira Code', 'Consolas', monospace;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-hover); }

img { max-width: 100%; display: block; }

button {
  font-family: var(--font);
  cursor: pointer;
  border: none;
  background: none;
  color: var(--text-primary);
  font-size: inherit;
}

/* ── Utility ── */
.container { max-width: 1320px; margin: 0 auto; padding: 0 20px; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.gap-20 { gap: 20px; }
.gap-24 { gap: 24px; }
.text-positive { color: var(--positive); }
.text-negative { color: var(--negative); }
.text-accent { color: var(--accent); }
.text-secondary { color: var(--text-secondary); }
.text-muted { color: var(--text-muted); }
.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }
.tabular { font-variant-numeric: tabular-nums; }

/* ── Scrollbar ── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ── Navigation ── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  height: 56px;
  display: flex;
  align-items: center;
}
.nav-inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 20px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--white);
  letter-spacing: -0.02em;
}
.nav-logo svg { width: 28px; height: 28px; }
.nav-links { display: flex; align-items: center; gap: 4px; }
.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-surface-hover);
}
.nav-links a.active { color: var(--accent); }
.nav-right { display: flex; align-items: center; gap: 12px; }
.nav-search {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-muted);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color var(--transition);
}
.nav-search:hover { border-color: var(--border-light); }
.nav-search kbd {
  background: var(--bg-surface-hover);
  padding: 1px 5px;
  border-radius: 3px;
  font-size: 0.75rem;
  font-family: var(--font);
  color: var(--text-muted);
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 18px;
  border-radius: var(--radius);
  font-weight: 500;
  font-size: 0.9rem;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary { background: var(--accent); color: var(--white); }
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  background: transparent;
  border: 1px solid var(--border-light);
  color: var(--text-primary);
}
.btn-outline:hover { background: var(--bg-surface-hover); border-color: var(--text-muted); }
.btn-ghost { color: var(--text-secondary); }
.btn-ghost:hover { color: var(--text-primary); background: var(--bg-surface-hover); }
.btn-sm { padding: 5px 12px; font-size: 0.82rem; }

/* ── Hero ── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  left: 50%;
  transform: translateX(-50%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(41, 98, 255, 0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero h1 {
  font-size: 2.8rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--white);
  max-width: 680px;
  margin: 0 auto 16px;
  letter-spacing: -0.03em;
}
.hero p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 540px;
  margin: 0 auto 32px;
  line-height: 1.6;
}
.hero-buttons { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.hero-buttons .btn { padding: 12px 28px; font-size: 1rem; }

/* ── Market Summary Bar ── */
.market-summary {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 10px 0;
}
.market-ticker-wrap {
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.market-ticker-wrap::-webkit-scrollbar { display: none; }
.market-ticker {
  display: flex;
  gap: 24px;
  min-width: max-content;
  padding: 4px 0;
}
.market-ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
  font-size: 0.85rem;
}
.market-ticker-item .ticker-name { color: var(--text-secondary); font-weight: 500; }
.market-ticker-item .ticker-price { color: var(--text-primary); font-weight: 500; font-variant-numeric: tabular-nums; }
.market-ticker-item .ticker-change { font-weight: 500; font-variant-numeric: tabular-nums; }

/* ── Section ── */
.section {
  padding: 40px 0;
  border-bottom: 1px solid var(--border);
}
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  gap: 16px;
}
.section-title {
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--white);
}
.section-link {
  font-size: 0.85rem;
  color: var(--accent);
  font-weight: 500;
}

/* ── Tabs ── */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 3px;
  overflow-x: auto;
}
.tab-btn {
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all var(--transition);
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  background: var(--accent);
  color: var(--white);
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* ── Card ── */
.card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 16px;
  transition: border-color var(--transition);
}
.card:hover { border-color: var(--border-light); }

/* ── Badge ── */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-neutral { background: var(--bg-surface-hover); color: var(--text-secondary); }
.badge-tier {
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
