.badge-platinum { background: linear-gradient(135deg, #a8a8a8, #e8e8e8); color: #1a1a2e; }
.badge-gold { background: linear-gradient(135deg, #d4a017, #f5d060); color: #1a1a2e; }

/* ── Table ── */
.data-table {
