}
.data-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.data-table tr:hover td { background: var(--bg-surface-hover); }
.data-table tr:last-child td { border-bottom: none; }
.data-table .ticker-symbol {
  color: var(--text-primary);
  font-weight: 600;
}
.data-table .company-name {
  color: var(--text-secondary);
  font-size: 0.82rem;
}

/* ── Sparkline ── */
.sparkline { display: inline-block; vertical-align: middle; }

/* ── Stock Item (trending) ── */
.stock-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
}
.stock-item:last-child { border-bottom: none; }
.stock-item-info { display: flex; flex-direction: column; gap: 2px; }
.stock-item-ticker { font-weight: 600; color: var(--text-primary); font-size: 0.95rem; }
.stock-item-name { font-size: 0.78rem; color: var(--text-secondary); }
.stock-item-price { font-weight: 500; font-variant-numeric: tabular-nums; }

/* ── Idea Card ── */
.idea-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
