  height: 180px;
  background: var(--bg-surface-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.idea-card-img svg { opacity: 0.3; }
.idea-card-body { padding: 16px; }
.idea-card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}
.idea-card-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--accent);
}
.idea-card-author { font-size: 0.82rem; font-weight: 500; color: var(--text-primary); }
.idea-card-time { font-size: 0.75rem; color: var(--text-muted); }
.idea-card-title {
  font-size: 0.92rem;
