.idea-card-footer span { display: flex; align-items: center; gap: 4px; }

/* ── Chart Page Layout ── */
.chart-workspace {
  display: grid;
  grid-template-columns: 220px 1fr 300px;
  grid-template-rows: auto 1fr auto;
  height: calc(100vh - 56px);
  overflow: hidden;
