.chart-toolbar {
  grid-column: 1 / -1;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 6px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
}
.toolbar-group {
  display: flex;
  align-items: center;
  gap: 2px;
