  padding: 8px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 0.82rem;
  outline: none;
  margin: 8px 12px;
  width: calc(100% - 24px);
}
.watchlist-search::placeholder { color: var(--text-muted); }
.watchlist-search:focus { border-color: var(--accent); }
.watchlist-category {
  border-bottom: 1px solid var(--border);
}
.watchlist-category-header {
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  user-select: none;
  transition: background var(--transition);
}
.watchlist-category-header:hover { background: var(--bg-surface-hover); }
.watchlist-category-header h4 {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
}
.watchlist-category-header .chevron {
  transition: transform var(--transition-mid);
  color: var(--text-muted);
}
.watchlist-category.open .chevron { transform: rotate(180deg); }
.watchlist-items { display: none; }
.watchlist-category.open .watchlist-items { display: block; }
.watchlist-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 12px;
  padding: 8px 12px;
  cursor: pointer;
  transition: background var(--transition);
  align-items: center;
  font-size: 0.82rem;
}
.watchlist-item:hover { background: var(--bg-surface-hover); }
.watchlist-item.active { background: var(--accent-dim); }
.watchlist-item-symbol { font-weight: 600; color: var(--text-primary); }
.watchlist-item-last { font-variant-numeric: tabular-nums; color: var(--text-primary); }
.watchlist-item-chg { font-variant-numeric: tabular-nums; text-align: right; }

/* Chart Area */
.chart-main {
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}
.chart-canvas {
  width: 100%;
  height: 100%;
  display: block;
}
.chart-timeframe {
  position: absolute;
  top: 12px;
  right: 12px;
  display: flex;
  gap: 2px;
  background: rgba(19, 23, 34, 0.9);
  border-radius: var(--radius);
  padding: 3px;
  backdrop-filter: blur(8px);
  z-index: 5;
}
.tf-btn {
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition);
}
.tf-btn:hover { color: var(--text-primary); }
.tf-btn.active { background: var(--accent); color: var(--white); }

/* Detail Panel */
.detail-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  overflow-y: auto;
  grid-row: 2 / 4;
}
.detail-header {
  padding: 16px;
  border-bottom: 1px solid var(--border);
}
.detail-ticker {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--white);
}
.detail-company { font-size: 0.82rem; color: var(--text-secondary); margin-top: 2px; }
.detail-price {
  margin-top: 12px;
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.detail-price-value { font-size: 1.8rem; font-weight: 700; font-variant-numeric: tabular-nums; }
.detail-price-change { font-size: 0.9rem; font-weight: 500; font-variant-numeric: tabular-nums; }
.detail-section {
  padding: 16px;
  border-bottom: 1px solid var(--border);
}
.detail-section-title {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 12px;
}
.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 0;
  font-size: 0.82rem;
}
.detail-row-label { color: var(--text-secondary); }
.detail-row-value { font-weight: 500; font-variant-numeric: tabular-nums; }
.detail-headline {
  margin-top: 8px;
  padding: 10px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  font-size: 0.82rem;
  color: var(--text-secondary);
  line-height: 1.5;
}
.detail-tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
}
.detail-tab {
  flex: 1;
  padding: 10px;
  text-align: center;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}
.detail-tab:hover { color: var(--text-primary); }
.detail-tab.active { color: var(--accent); border-bottom-color: var(--accent); }

/* ── Broker Card ── */
.broker-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 16px;
  transition: border-color var(--transition);
}
.broker-card:hover { border-color: var(--border-light); }
.broker-header { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.broker-logo {
  width: 48px;
  height: 48px;
  background: var(--bg-surface-hover);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.8rem;
  color: var(--accent);
}
.broker-info h3 { font-size: 1rem; font-weight: 600; color: var(--white); }
.broker-info p { font-size: 0.82rem; color: var(--text-secondary); }
.broker-stats { display: flex; gap: 20px; flex-wrap: wrap; }
.broker-stat { display: flex; flex-direction: column; gap: 2px; }
.broker-stat-label { font-size: 0.72rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.broker-stat-value { font-size: 0.92rem; font-weight: 600; font-variant-numeric: tabular-nums; }
.broker-rating { display: flex; align-items: center; gap: 6px; }
.broker-stars { color: #FFB800; font-size: 0.85rem; letter-spacing: 1px; }
.broker-promo {
  padding: 8px 14px;
  background: var(--accent-dim);
  border: 1px solid rgba(41, 98, 255, 0.25);
  border-radius: var(--radius);
  font-size: 0.82rem;
  color: var(--accent);
  font-weight: 500;
}
.broker-actions { display: flex; flex-direction: column; align-items: flex-end; gap: 10px; justify-content: center; }

/* ── Stats Banner ── */
.stats-banner {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-surface));
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 48px 0;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 32px;
  text-align: center;
}
.stat-item h3 { font-size: 2.2rem; font-weight: 700; color: var(--white); font-variant-numeric: tabular-nums; }
.stat-item p { font-size: 0.9rem; color: var(--text-secondary); margin-top: 4px; }

/* ── Footer ── */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 48px 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  margin-bottom: 32px;
}
.footer-col h4 {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  font-size: 0.85rem;
  color: var(--text-muted);
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  flex-wrap: wrap;
  gap: 12px;
}

/* ── Pagination ── */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
}
.page-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition);
}
.page-btn:hover { background: var(--bg-surface-hover); color: var(--text-primary); }
.page-btn.active { background: var(--accent); color: var(--white); }

/* ── Market Page Specific ── */
.market-nav {
  display: flex;
  gap: 2px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 3px;
  overflow-x: auto;
  margin-bottom: 24px;
}
.market-nav-btn {
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all var(--transition);
}
.market-nav-btn:hover { color: var(--text-primary); }
.market-nav-btn.active { background: var(--accent); color: var(--white); }

.chart-options {
  display: flex;
  gap: 2px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 3px;
  margin-bottom: 16px;
}

/* ── Gainers/Losers ── */
.mover-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 16px;
}
.mover-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}
.mover-item:last-child { border-bottom: none; }
.mover-rank { width: 24px; font-size: 0.78rem; color: var(--text-muted); font-weight: 500; }
.mover-name { flex: 1; font-size: 0.85rem; color: var(--text-primary); margin-left: 8px; }
.mover-change { font-weight: 600; font-variant-numeric: tabular-nums; font-size: 0.85rem; }

/* ── Earnings ── */
.earnings-row {
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
  align-items: center;
  font-size: 0.85rem;
}
.earnings-row:last-child { border-bottom: none; }
.earnings-date { color: var(--text-muted); font-weight: 500; }
.earnings-company { font-weight: 500; }
.earnings-actual { font-weight: 600; color: var(--positive); }
.earnings-estimate { color: var(--text-secondary); }

/* ── Ideas Page ── */
.ideas-header {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 20px 0;
}
.ideas-filters {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.filter-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.82rem;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-toggle:hover { border-color: var(--border-light); color: var(--text-primary); }
.filter-toggle.active { border-color: var(--accent); color: var(--accent); background: var(--accent-dim); }
.filter-toggle .toggle-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid var(--border-light);
  transition: all var(--transition);
}
.filter-toggle.active .toggle-dot {
  border-color: var(--accent);
  background: var(--accent);
}
.idea-feed {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 20px;
  padding: 24px 0;
}

/* ── Broker Filters ── */
.broker-filters {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 20px 0;
  border-bottom: 1px solid var(--border);
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .chart-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 50vh auto;
  }
  .watchlist { display: none; }
  .detail-panel { border-left: none; border-top: 1px solid var(--border); }
}
@media (max-width: 768px) {
  html { font-size: 13px; }
  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }
  .nav-links { display: none; }
  .nav-search { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .idea-feed { grid-template-columns: 1fr; }
  .broker-card { grid-template-columns: 1fr; }
  .broker-actions { flex-direction: row; align-items: center; }
}
@media (max-width: 480px) {
  .container { padding: 0 12px; }
  .hero { padding: 48px 0 40px; }
  .hero h1 { font-size: 1.6rem; }
  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
}
