/* ChartPulse — Design System & Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #131722;
  --bg-surface: #1E222D;
  --bg-surface-hover: #2A2E39;
  --bg-elevated: #252833;
  --bg-input: #1C2030;
  --accent: #2962FF;
  --accent-hover: #3D7AFF;
  --accent-dim: rgba(41, 98, 255, 0.12);
  --positive: #26A69A;
  --positive-bg: rgba(38, 166, 154, 0.1);
  --negative: #F7525F;
  --negative-bg: rgba(247, 82, 95, 0.1);
  --text-primary: #D1D4DC;
  --text-secondary: #787B86;
  --text-muted: #4A4E59;
  --border: #2A2E39;
  --border-light: #363A45;
  --white: #FFFFFF;
  --radius: 6px;
  --radius-lg: 10px;
  --radius-sm: 4px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.4);
  --transition: 150ms ease;
  --transition-mid: 250ms ease;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'SF Mono', 'Fira Code', 'Consolas', monospace;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-hover); }

img { max-width: 100%; display: block; }

button {
  font-family: var(--font);
  cursor: pointer;
  border: none;
  background: none;
  color: var(--text-primary);
  font-size: inherit;
}

/* ── Utility ── */
.container { max-width: 1320px; margin: 0 auto; padding: 0 20px; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.gap-20 { gap: 20px; }
.gap-24 { gap: 24px; }
.text-positive { color: var(--positive); }
.text-negative { color: var(--negative); }
.text-accent { color: var(--accent); }
.text-secondary { color: var(--text-secondary); }
.text-muted { color: var(--text-muted); }
.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }
.tabular { font-variant-numeric: tabular-nums; }

/* ── Scrollbar ── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ── Navigation ── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  height: 56px;
  display: flex;
  align-items: center;
}
.nav-inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 20px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--white);
  letter-spacing: -0.02em;
}
.nav-logo svg { width: 28px; height: 28px; }
.nav-links { display: flex; align-items: center; gap: 4px; }
.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-surface-hover);
}
.nav-links a.active { color: var(--accent); }
.nav-right { display: flex; align-items: center; gap: 12px; }
.nav-search {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-muted);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color var(--transition);
}
.nav-search:hover { border-color: var(--border-light); }
.nav-search kbd {
  background: var(--bg-surface-hover);
  padding: 1px 5px;
  border-radius: 3px;
  font-size: 0.75rem;
  font-family: var(--font);
  color: var(--text-muted);
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 18px;
  border-radius: var(--radius);
  font-weight: 500;
  font-size: 0.9rem;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary { background: var(--accent); color: var(--white); }
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  background: transparent;
  border: 1px solid var(--border-light);
  color: var(--text-primary);
}
.btn-outline:hover { background: var(--bg-surface-hover); border-color: var(--text-muted); }
.btn-ghost { color: var(--text-secondary); }
.btn-ghost:hover { color: var(--text-primary); background: var(--bg-surface-hover); }
.btn-sm { padding: 5px 12px; font-size: 0.82rem; }

/* ── Hero ── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  left: 50%;
  transform: translateX(-50%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(41, 98, 255, 0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero h1 {
  font-size: 2.8rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--white);
  max-width: 680px;
  margin: 0 auto 16px;
  letter-spacing: -0.03em;
}
.hero p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 540px;
  margin: 0 auto 32px;
  line-height: 1.6;
}
.hero-buttons { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.hero-buttons .btn { padding: 12px 28px; font-size: 1rem; }

/* ── Market Summary Bar ── */
.market-summary {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 10px 0;
}
.market-ticker-wrap {
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.market-ticker-wrap::-webkit-scrollbar { display: none; }
.market-ticker {
  display: flex;
  gap: 24px;
  min-width: max-content;
  padding: 4px 0;
}
.market-ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
  font-size: 0.85rem;
}
.market-ticker-item .ticker-name { color: var(--text-secondary); font-weight: 500; }
.market-ticker-item .ticker-price { color: var(--text-primary); font-weight: 500; font-variant-numeric: tabular-nums; }
.market-ticker-item .ticker-change { font-weight: 500; font-variant-numeric: tabular-nums; }

/* ── Section ── */
.section {
  padding: 40px 0;
  border-bottom: 1px solid var(--border);
}
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  gap: 16px;
}
.section-title {
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--white);
}
.section-link {
  font-size: 0.85rem;
  color: var(--accent);
  font-weight: 500;
}

/* ── Tabs ── */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 3px;
  overflow-x: auto;
}
.tab-btn {
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all var(--transition);
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  background: var(--accent);
  color: var(--white);
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* ── Card ── */
.card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 16px;
  transition: border-color var(--transition);
}
.card:hover { border-color: var(--border-light); }

/* ── Badge ── */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-neutral { background: var(--bg-surface-hover); color: var(--text-secondary); }
.badge-tier {
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.badge-platinum { background: linear-gradient(135deg, #a8a8a8, #e8e8e8); color: #1a1a2e; }
.badge-gold { background: linear-gradient(135deg, #d4a017, #f5d060); color: #1a1a2e; }

/* ── Table ── */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}
.data-table th {
  text-align: left;
  padding: 10px 12px;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}
.data-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.data-table tr:hover td { background: var(--bg-surface-hover); }
.data-table tr:last-child td { border-bottom: none; }
.data-table .ticker-symbol {
  color: var(--text-primary);
  font-weight: 600;
}
.data-table .company-name {
  color: var(--text-secondary);
  font-size: 0.82rem;
}

/* ── Sparkline ── */
.sparkline { display: inline-block; vertical-align: middle; }

/* ── Stock Item (trending) ── */
.stock-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
}
.stock-item:last-child { border-bottom: none; }
.stock-item-info { display: flex; flex-direction: column; gap: 2px; }
.stock-item-ticker { font-weight: 600; color: var(--text-primary); font-size: 0.95rem; }
.stock-item-name { font-size: 0.78rem; color: var(--text-secondary); }
.stock-item-price { font-weight: 500; font-variant-numeric: tabular-nums; }

/* ── Idea Card ── */
.idea-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition);
}
.idea-card:hover { border-color: var(--border-light); }
.idea-card-img {
  width: 100%;
  height: 180px;
  background: var(--bg-surface-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.idea-card-img svg { opacity: 0.3; }
.idea-card-body { padding: 16px; }
.idea-card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}
.idea-card-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--accent);
}
.idea-card-author { font-size: 0.82rem; font-weight: 500; color: var(--text-primary); }
.idea-card-time { font-size: 0.75rem; color: var(--text-muted); }
.idea-card-title {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 6px;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.idea-card-tags { display: flex; gap: 6px; flex-wrap: wrap; }
.idea-tag {
  padding: 2px 8px;
  background: var(--bg-surface-hover);
  border-radius: 100px;
  font-size: 0.72rem;
  color: var(--text-secondary);
}
.idea-card-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
  font-size: 0.78rem;
  color: var(--text-muted);
}
.idea-card-footer span { display: flex; align-items: center; gap: 4px; }

/* ── Chart Page Layout ── */
.chart-workspace {
  display: grid;
  grid-template-columns: 220px 1fr 300px;
  grid-template-rows: auto 1fr auto;
  height: calc(100vh - 56px);
  overflow: hidden;
}
.chart-toolbar {
  grid-column: 1 / -1;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 6px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
}
.toolbar-group {
  display: flex;
  align-items: center;
  gap: 2px;
}
.toolbar-divider {
  width: 1px;
  height: 24px;
  background: var(--border);
  margin: 0 6px;
}
.toolbar-btn {
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition);
}
.toolbar-btn:hover { color: var(--text-primary); background: var(--bg-surface-hover); }
.toolbar-btn.active { color: var(--accent); background: var(--accent-dim); }

/* Watchlist */
.watchlist {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  overflow-y: auto;
  grid-row: 2 / 4;
}
.watchlist-header {
  padding: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--bg-secondary);
  z-index: 5;
}
.watchlist-header h3 { font-size: 0.9rem; font-weight: 600; }
.watchlist-search {
  width: 100%;
  padding: 8px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 0.82rem;
  outline: none;
  margin: 8px 12px;
  width: calc(100% - 24px);
}
.watchlist-search::placeholder { color: var(--text-muted); }
.watchlist-search:focus { border-color: var(--accent); }
.watchlist-category {
  border-bottom: 1px solid var(--border);
}
.watchlist-category-header {
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  user-select: none;
  transition: background var(--transition);
}
.watchlist-category-header:hover { background: var(--bg-surface-hover); }
.watchlist-category-header h4 {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
}
.watchlist-category-header .chevron {
  transition: transform var(--transition-mid);
  color: var(--text-muted);
}
.watchlist-category.open .chevron { transform: rotate(180deg); }
.watchlist-items { display: none; }
.watchlist-category.open .watchlist-items { display: block; }
.watchlist-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 12px;
  padding: 8px 12px;
  cursor: pointer;
  transition: background var(--transition);
  align-items: center;
  font-size: 0.82rem;
}
.watchlist-item:hover { background: var(--bg-surface-hover); }
.watchlist-item.active { background: var(--accent-dim); }
.watchlist-item-symbol { font-weight: 600; color: var(--text-primary); }
.watchlist-item-last { font-variant-numeric: tabular-nums; color: var(--text-primary); }
.watchlist-item-chg { font-variant-numeric: tabular-nums; text-align: right; }

/* Chart Area */
.chart-main {
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}
.chart-canvas {
  width: 100%;
  height: 100%;
  display: block;
}
.chart-timeframe {
  position: absolute;
  top: 12px;
  right: 12px;
  display: flex;
  gap: 2px;
  background: rgba(19, 23, 34, 0.9);
  border-radius: var(--radius);
  padding: 3px;
  backdrop-filter: blur(8px);
  z-index: 5;
}
.tf-btn {
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition);
}
.tf-btn:hover { color: var(--text-primary); }
.tf-btn.active { background: var(--accent); color: var(--white); }

