  border-bottom: 1px solid var(--border);
}
.detail-ticker {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--white);
}
.detail-company { font-size: 0.82rem; color: var(--text-secondary); margin-top: 2px; }
.detail-price {
  margin-top: 12px;
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.detail-price-value { font-size: 1.8rem; font-weight: 700; font-variant-numeric: tabular-nums; }
.detail-price-change { font-size: 0.9rem; font-weight: 500; font-variant-numeric: tabular-nums; }
.detail-section {
  padding: 16px;
  border-bottom: 1px solid var(--border);
