.broker-rating { display: flex; align-items: center; gap: 6px; }
.broker-stars { color: #FFB800; font-size: 0.85rem; letter-spacing: 1px; }
.broker-promo {
  padding: 8px 14px;
  background: var(--accent-dim);
  border: 1px solid rgba(41, 98, 255, 0.25);
  border-radius: var(--radius);
  font-size: 0.82rem;
  color: var(--accent);
  font-weight: 500;
