1	/* ChartPulse — Shared JavaScript */
2	document.addEventListener('DOMContentLoaded', () => {
3	
4	  // ── Tab Switching ──
5	  document.querySelectorAll('.tabs, .detail-tabs, .market-nav, .chart-timeframe, .chart-options, .broker-filters').forEach(tabGroup => {
6	    tabGroup.addEventListener('click', e => {
7	      const btn = e.target.closest('.tab-btn, .detail-tab, .market-nav-btn, .tf-btn, .broker-cat-btn');
8	      if (!btn) return;
9	      const siblings = btn.parentElement.children;
10	      for (const s of siblings) s.classList.remove('active');
11	      btn.classList.add('active');
12	
13	      // If tabs control content panels
14	      const tabId = btn.dataset.tab;
15	      if (tabId) {
16	        const container = btn.closest('.section, .detail-panel, .market-content, .broker-listings-wrap') || document;
17	        container.querySelectorAll('.tab-content').forEach(tc => tc.classList.remove('active'));
18	        const target = container.querySelector(`[data-tab-content="${tabId}"]`);
19	        if (target) target.classList.add('active');
20	      }
21	    });
22	  });
23	
24	  // ── Accordion (Watchlist) ──
25	  document.querySelectorAll('.watchlist-category-header').forEach(header => {
26	    header.addEventListener('click', () => {
27	      const cat = header.closest('.watchlist-category');
28	      cat.classList.toggle('open');
29	    });
30	  });
31	
32	  // ── Filter Toggles ──
33	  document.querySelectorAll('.filter-toggle').forEach(toggle => {
34	    toggle.addEventListener('click', () => {
35	      toggle.classList.toggle('active');
36	    });
37	  });
38	
39	  // ── Watchlist Item Click ──
40	  document.querySelectorAll('.watchlist-item').forEach(item => {
41	    item.addEventListener('click', () => {
42	      document.querySelectorAll('.watchlist-item').forEach(i => i.classList.remove('active'));
43	      item.classList.add('active');
44	    });
45	  });
46	
47	  // ── Draw Candlestick Chart ──
48	  const chartCanvas = document.getElementById('candlestickCanvas');
49	  if (chartCanvas) {
50	    drawCandlestickChart(chartCanvas);
51	    window.addEventListener('resize', () => drawCandlestickChart(chartCanvas));
52	  }
53	
54	  // ── Draw Sparklines ──
55	  document.querySelectorAll('.sparkline-canvas').forEach(canvas => {
56	    drawSparkline(canvas);
57	  });
58	
59	  // ── Draw mini charts on markets page ──
60	  document.querySelectorAll('.mini-chart-canvas').forEach(canvas => {
61	    drawMiniChart(canvas);
62	  });
63	});
64	
65	function drawCandlestickChart(canvas) {
66	  const ctx = canvas.getContext('2d');
67	  const rect = canvas.parentElement.getBoundingClientRect();
68	  const dpr = window.devicePixelRatio || 1;
69	  canvas.width = rect.width * dpr;
70	  canvas.height = rect.height * dpr;
71	  canvas.style.width = rect.width + 'px';
72	  canvas.style.height = rect.height + 'px';
73	  ctx.scale(dpr, dpr);
74	  const W = rect.width;
75	  const H = rect.height;
76	
77	  // Generate realistic-looking candle data
78	  const numCandles = 60;
79	  const data = [];
80	  let price = 260;
81	  for (let i = 0; i < numCandles; i++) {
82	    const open = price + (Math.random() - 0.48) * 4;
83	    const close = open + (Math.random() - 0.48) * 6;
84	    const high = Math.max(open, close) + Math.random() * 3;
85	    const low = Math.min(open, close) - Math.random() * 3;
86	    data.push({ open, close, high, low });
87	    price = close;
88	  }
89	
90	  const allPrices = data.flatMap(d => [d.high, d.low]);
91	  const minP = Math.min(...allPrices) - 2;
92	  const maxP = Math.max(...allPrices) + 2;
93	  const range = maxP - minP;
94	
95	  const pad = { top: 20, right: 60, bottom: 30, left: 10 };
96	  const chartW = W - pad.left - pad.right;
97	  const chartH = H - pad.top - pad.bottom;
98	  const candleW = chartW / numCandles;
99	  const bodyW = candleW * 0.65;
100	
101	  const yScale = p => pad.top + chartH - ((p - minP) / range) * chartH;
102	
103	  // Background
104	  ctx.fillStyle = '#0F0F0F';
105	  ctx.fillRect(0, 0, W, H);
106	
107	  // Grid
108	  ctx.strokeStyle = '#1E222D';
109	  ctx.lineWidth = 1;
110	  const gridLines = 6;
111	  for (let i = 0; i <= gridLines; i++) {
112	    const y = pad.top + (chartH / gridLines) * i;
113	    ctx.beginPath();
114	    ctx.moveTo(pad.left, y);
115	    ctx.lineTo(W - pad.right, y);
116	    ctx.stroke();
117	    // Price labels
118	    const pVal = maxP - (range / gridLines) * i;
119	    ctx.fillStyle = '#4A4E59';
120	    ctx.font = '11px Inter, sans-serif';
121	    ctx.textAlign = 'left';
122	    ctx.fillText(pVal.toFixed(2), W - pad.right + 8, y + 4);
123	  }
124	
125	  // Volume bars
126	  const maxVol = 50;
127	  for (let i = 0; i < numCandles; i++) {
128	    const x = pad.left + i * candleW + candleW / 2;
129	    const vol = Math.random() * maxVol;
130	    const volH = (vol / maxVol) * (chartH * 0.15);
131	    const isGreen = data[i].close >= data[i].open;
132	    ctx.fillStyle = isGreen ? 'rgba(38,166,154,0.15)' : 'rgba(247,82,95,0.15)';
133	    ctx.fillRect(x - bodyW / 2, H - pad.bottom - volH, bodyW, volH);
134	  }
135	
136	  // Candles
137	  for (let i = 0; i < numCandles; i++) {
138	    const d = data[i];
139	    const x = pad.left + i * candleW + candleW / 2;
140	    const isGreen = d.close >= d.open;
141	    const color = isGreen ? '#26A69A' : '#F7525F';
142	
143	    // Wick
144	    ctx.strokeStyle = color;
145	    ctx.lineWidth = 1;
146	    ctx.beginPath();
147	    ctx.moveTo(x, yScale(d.high));
148	    ctx.lineTo(x, yScale(d.low));
149	    ctx.stroke();
150	
151	    // Body
152	    const bodyTop = yScale(Math.max(d.open, d.close));
153	    const bodyBot = yScale(Math.min(d.open, d.close));
154	    ctx.fillStyle = color;
155	    ctx.fillRect(x - bodyW / 2, bodyTop, bodyW, Math.max(bodyBot - bodyTop, 1));
156	  }
157	
158	  // Current price line
159	  const lastPrice = data[data.length - 1].close;
160	  const lastY = yScale(lastPrice);
161	  ctx.setLineDash([4, 4]);
162	  ctx.strokeStyle = '#26A69A';
163	  ctx.lineWidth = 1;
164	  ctx.beginPath();
165	  ctx.moveTo(pad.left, lastY);
166	  ctx.lineTo(W - pad.right, lastY);
167	  ctx.stroke();
168	  ctx.setLineDash([]);
169	
170	  // Price label
171	  ctx.fillStyle = '#26A69A';
172	  ctx.fillRect(W - pad.right, lastY - 10, 56, 20);
173	  ctx.fillStyle = '#FFFFFF';
174	  ctx.font = 'bold 11px Inter, sans-serif';
175	  ctx.textAlign = 'left';
176	  ctx.fillText(lastPrice.toFixed(2), W - pad.right + 4, lastY + 4);
177	
178	  // Date labels
179	  ctx.fillStyle = '#4A4E59';
180	  ctx.font = '10px Inter, sans-serif';
181	  ctx.textAlign = 'center';
182	  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
183	  for (let i = 0; i < numCandles; i += 10) {
184	    const x = pad.left + i * candleW + candleW / 2;
185	    const d = new Date(2026, 0, 1);
186	    d.setDate(d.getDate() + i);
187	    ctx.fillText(`${months[d.getMonth()]} ${d.getDate()}`, x, H - 8);
188	  }
189	}
190	
191	function drawSparkline(canvas) {
192	  const ctx = canvas.getContext('2d');
193	  const isPositive = canvas.dataset.trend === 'positive';
194	  const W = canvas.width;
195	  const H = canvas.height;
196	  const points = [];
197	  let val = 50;
198	  for (let i = 0; i < 20; i++) {
199	    val += (Math.random() - (isPositive ? 0.4 : 0.6)) * 5;
200	    points.push(val);
201	  }
202	  const min = Math.min(...points) - 5;
203	  const max = Math.max(...points) + 5;
204	  const stepX = W / (points.length - 1);
205	
206	  ctx.beginPath();
207	  points.forEach((p, i) => {
208	    const x = i * stepX;
209	    const y = H - ((p - min) / (max - min)) * H;
210	    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
211	  });
212	  ctx.strokeStyle = isPositive ? '#26A69A' : '#F7525F';
213	  ctx.lineWidth = 1.5;
214	  ctx.stroke();
215	}
216	
217	function drawMiniChart(canvas) {
218	  const ctx = canvas.getContext('2d');
219	  const dpr = window.devicePixelRatio || 1;
220	  const displayW = canvas.clientWidth;
221	  const displayH = canvas.clientHeight;
222	  canvas.width = displayW * dpr;
223	  canvas.height = displayH * dpr;
224	  ctx.scale(dpr, dpr);
225	
226	  const isPositive = canvas.dataset.trend === 'positive';
227	  const points = [];
228	  let val = 50;
229	  for (let i = 0; i < 30; i++) {
230	    val += (Math.random() - (isPositive ? 0.4 : 0.6)) * 4;
231	    points.push(val);
232	  }
233	  const min = Math.min(...points) - 5;
234	  const max = Math.max(...points) + 5;
235	  const stepX = displayW / (points.length - 1);
236	  const color = isPositive ? '#26A69A' : '#F7525F';
237	
238	  // Area fill
239	  ctx.beginPath();
240	  points.forEach((p, i) => {
241	    const x = i * stepX;
242	    const y = displayH - ((p - min) / (max - min)) * displayH;
243	    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
244	  });
245	  ctx.lineTo(displayW, displayH);
246	  ctx.lineTo(0, displayH);
247	  ctx.closePath();
248	  const grad = ctx.createLinearGradient(0, 0, 0, displayH);
249	  grad.addColorStop(0, isPositive ? 'rgba(38,166,154,0.2)' : 'rgba(247,82,95,0.2)');
250	  grad.addColorStop(1, 'rgba(0,0,0,0)');
251	  ctx.fillStyle = grad;
252	  ctx.fill();
253	
254	  // Line
255	  ctx.beginPath();
256	  points.forEach((p, i) => {
257	    const x = i * stepX;
258	    const y = displayH - ((p - min) / (max - min)) * displayH;
259	    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
260	  });
261	  ctx.strokeStyle = color;
262	  ctx.lineWidth = 1.5;
263	  ctx.stroke();
264	}
